package com.evolution.analysis.filesystem;

import com.evolution.analysis.acquisition.streaming.*;
import com.evolution.analysis.contract.common.*;
import com.evolution.analysis.contract.identity.*;
import com.evolution.analysis.contract.serialization.CanonicalJson;
import com.evolution.analysis.evidence.EvidenceContext;
import com.evolution.analysis.execution.EvidenceVerifier;
import com.evolution.analysis.polyglot.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Publication protocol controls, never production method registrations. The
 * empty repository isolates publication; nonempty child proofs are tested in analyzer. */
class SemanticAuthenticatedPublicationTest {
    @TempDir Path directory;
    @Test void coldPublicationRequiresLiveAuthorityAndRevocationInvalidatesQueries()throws Exception {
        var content=new StreamingContentStore(directory.resolve("cas"));var tables=new SemanticTables(content,65536);var generator=KeyPairGenerator.getInstance("Ed25519");var controller=generator.generateKeyPair();var validator=generator.generateKeyPair();var tool=ContentDigest.sha256Utf8("authored-root-tool");
        var method=new EvidenceVerifier.Method(new VersionedIdentifier("authored.empty-root","v1"),new VersionedIdentifier("polyglot.root-census","m8.4-v1"),tool,List.of("SEALED_SOURCE_MEMBERSHIP","EFFECTIVE_CONTEXT_CLOSURE","GENERATED_EXTERNAL_LINEAGE","EMBEDDED_SOURCE_MAPPING"));var verifier=new EvidenceVerifier(Map.of("controller",controller.getPublic()),Map.of("validator",validator.getPublic()),List.of(method));
        var inventory=ContentDigest.sha256Utf8("empty-source-inventory");var root=EvidenceContext.forSnapshot(SnapshotIdentity.from(RepositoryIdentity.fromCanonicalCoordinate("urn:test:authenticated-publication"),inventory));var documents=tables.write(SemanticTables.Kind.DOCUMENT,Collections.emptyIterator(),()->false);var coordinator=new SemanticContextCoordinator(content,tables);var plan=coordinator.plan(root,new PolyglotInventory.Report(inventory,documents,0,0),Collections.emptyIterator(),verifier.policyIdentity(),()->false);
        var input=new SemanticRootCensus.Input(tables.write(SemanticTables.Kind.CENSUS,Collections.emptyIterator(),()->false),tables.write(SemanticTables.Kind.CONTEXT,Collections.emptyIterator(),()->false),documents,tool);SemanticContextCoordinator.CensusIndex indexes=()->new SqliteSemanticCensusIndex(directory.resolve("scratch-"+UUID.randomUUID()+".sqlite"),65536);SemanticRootCensus.Accounting accounting;
        try(var index=indexes.open()){accounting=new SemanticRootCensus(content,tables).reconcile(plan,input,index,Optional.empty(),Set.of(),plan::policy,()->false).accounting();}
        var payload=content.put(new ByteArrayInputStream(CanonicalJson.write(SemanticRootCensus.proofPayload(plan,input,accounting)).getBytes(StandardCharsets.UTF_8)),()->false);var expected=new EvidenceVerifier.Expected(ContentDigest.sha256Utf8("launch"),ContentDigest.sha256Utf8("profile"),1,plan.identity(),SemanticRootCensus.inputClosure(plan,input),payload,method.method(),method.predicate(),tool);var receipt=new EvidenceVerifier.Receipt("execution-protected-receipt:m8.4-v1","authored-publication",1,expected.launch(),expected.profile(),ContentDigest.sha256Utf8("output"),ContentDigest.sha256Utf8("materials"),ContentDigest.sha256Utf8("termination"));var attestation=new EvidenceVerifier.Attestation("execution-protected-attestation:m8.4-v1",receipt.identity(),payload.digest(),expected.scope(),expected.inputClosure(),tool,method.method(),method.predicate(),method.requiredChecks(),true);
        var proof=verifier.verifyAccepted(expected,receipt,sign("controller",receipt,controller.getPrivate()),attestation,sign("validator",attestation,validator.getPrivate()),content).orElseThrow();var revocations=new AtomicReference<Set<ContentDigest>>(Set.of());var validation=new SemanticPublicationValidation(content,tables,(r,o)->Map.of(),(p,i)->Optional.of(proof),indexes,revocations::get,plan::policy);var result=coordinator.runWithRootCensus(plan,r->Optional.empty(),(r,o)->Map.of(),r->Optional.empty(),Optional.of(new SemanticContextCoordinator.RootCensus(input,indexes,Optional.of(proof))),Map.of(),Set.of(),plan::policy,c->{},()->false);assertTrue(result.complete());
        var operator=directory.resolve("operator-authority");Files.createDirectories(operator.resolve("claims"));var config=new TreeMap<String,Object>();config.put("schema","semantic-authority:m8.4-v1");config.put("controllers",Map.of("controller",Base64.getEncoder().encodeToString(controller.getPublic().getEncoded())));config.put("validators",Map.of("validator",Base64.getEncoder().encodeToString(validator.getPublic().getEncoded())));config.put("methods",List.of(method));config.put("revoked",List.of());Files.writeString(operator.resolve("authority.json"),CanonicalJson.write(config));var signed=Map.of("expected",expected,"receipt",receipt,"controllerSignature",sign("controller",receipt,controller.getPrivate()),"attestation",attestation,"validatorSignature",sign("validator",attestation,validator.getPrivate()));var claimFile=operator.resolve("claims").resolve(SemanticAuthorityStore.rootKey(plan,input).value().substring(7)+".json");Files.writeString(claimFile,CanonicalJson.write(Map.of("schema","semantic-signed-claims:m8.4-v1","claims",Map.of("root",signed))));
        var configured=new SemanticAuthorityStore(operator,content,tables,plan.policy());assertEquals(proof.identity(),configured.rootClaim(plan,input).orElseThrow().identity());var heads=directory.resolve("heads");assertThrows(IOException.class,()->new SemanticPublicationStore(heads,content,tables).commit(plan,result,Optional.empty(),plan::policy,()->false));var store=new SemanticPublicationStore(heads,content,tables,Optional.of(configured.validation(indexes)));var publication=store.commit(plan,result,Optional.empty(),plan::policy,()->false);var cold=new SemanticPublicationStore(heads,content,new SemanticTables(content,65536),Optional.of(new SemanticAuthorityStore(operator,content,tables,plan.policy()).validation(indexes)));assertEquals(publication,cold.load(plan.identity(),plan::policy,()->false).orElseThrow());assertThrows(IOException.class,()->new SemanticPublicationStore(heads,content,tables).load(plan.identity(),plan::policy,()->false));
        var summary=cold.queries(plan::policy).summary(plan.identity(),()->false);assertTrue(summary.complete());assertEquals("VALIDATED_OBSERVATION",summary.trust());assertEquals("CURRENT_POLICY_VALIDATED",summary.qualification());assertEquals("LIVE_VALIDATED_ACCOUNTING",summary.accounting().get("availability"));assertEquals("",summary.rootGap());assertTrue(cold.queries(plan::policy).rootGaps(plan.identity(),10,Optional.empty(),()->false).items().isEmpty());
        config.put("revoked",List.of(proof.identity()));Files.writeString(operator.resolve("authority.json"),CanonicalJson.write(config));assertThrows(IOException.class,()->cold.load(plan.identity(),plan::policy,()->false));assertThrows(IOException.class,()->cold.queries(plan::policy).summary(plan.identity(),()->false));assertEquals(publication,cold.head(plan.identity()).orElseThrow());
        config.put("revoked",List.of());Files.writeString(operator.resolve("authority.json"),CanonicalJson.write(config));var corrupted=new TreeMap<String,Object>(signed);corrupted.put("validatorSignature",new EvidenceVerifier.SignatureEnvelope("validator","AA=="));Files.writeString(claimFile,CanonicalJson.write(Map.of("schema","semantic-signed-claims:m8.4-v1","claims",Map.of("root",corrupted))));assertThrows(IOException.class,()->cold.load(plan.identity(),plan::policy,()->false));config.put("methods",List.of());Files.writeString(operator.resolve("authority.json"),CanonicalJson.write(config));assertThrows(IOException.class,()->new SemanticAuthorityStore(operator,content,tables,plan.policy()));
    }
    private static EvidenceVerifier.SignatureEnvelope sign(String key,Object payload,PrivateKey privateKey)throws Exception {var signature=Signature.getInstance("Ed25519");signature.initSign(privateKey);signature.update(CanonicalJson.write(Map.of("keyId",key,"payload",payload)).getBytes(StandardCharsets.UTF_8));return new EvidenceVerifier.SignatureEnvelope(key,Base64.getEncoder().encodeToString(signature.sign()));}
}
